<?php $uid=(int)$me['id'];$factorRequired=$a->secondFactor->status($uid)['enabled'];$id=\Chengyu\Core\Input::integer($_GET['preview']??0);$preview=$id?$a->configuration->preview($uid,$id):null; ?>
<section class="page-hero"><div><span class="eyebrow">CONFIGURE WITH CONFIDENCE</span><h1><?= t('Configuration vault') ?></h1><p><?= t('Encrypted settings snapshots, visible differences, and a reversible restore.') ?></p></div><span class="page-hero-art"><?= icon('layers') ?></span></section><div class="alert info"><?= t('Settings only: no database, media, orders or user accounts. Archives require the original site key. Keep a full independent backup as well.') ?></div>
<?php if($preview): ?><section class="panel glass section"><div class="section-heading"><h2><?= t('Review before restoring') ?> #<?= $id ?></h2><span class="pill"><?= count($preview['changes']) ?> <?= t('Changes') ?></span></div><div class="snapshot-diff"><?php foreach($preview['changes'] as $change): ?><article><div><strong><?= t($change['label']) ?></strong><code><?= e($change['key']) ?></code></div><div><small><?= t('Current value') ?></small><pre><?= e(\Chengyu\Core\Input::clip(json_encode($change['before'],JSON_UNESCAPED_UNICODE),600)) ?></pre></div><div><small><?= t('Archived value') ?></small><pre><?= e(\Chengyu\Core\Input::clip(json_encode($change['after'],JSON_UNESCAPED_UNICODE),600)) ?></pre></div></article><?php endforeach ?></div><?= form_start('admin_snapshot_restore').hidden('id',$id).hidden('revision',$preview['revision']) ?><?php partial('factor_proof',['factorRequired'=>$factorRequired]);button('Verify and restore these settings','secondary','refresh'); ?><p class="hint"><?= t('The current settings are saved first. If anything changed after this preview, the restore is rejected and must be reviewed again.') ?></p></form></section><?php endif ?>
<div class="two-column section"><section class="panel glass"><h2><?= t('Save a settings snapshot') ?></h2><?= form_start('admin_snapshot_capture') ?><?php field('label','Snapshot label','','text',['required'=>'required','maxlength'=>'100']);button('Save encrypted snapshot','full','lock'); ?></form><p class="hint"><?= t('The latest 30 snapshots are retained. Download important archives before older ones are rotated out.') ?></p></section><section class="panel"><h2><?= t('Import an encrypted archive') ?></h2><?= str_replace('<form ','<form enctype="multipart/form-data" ',form_start('admin_snapshot_import','','',false)) ?><?php field('label','Snapshot label','','text',['required'=>'required','maxlength'=>'100']);field('archive','Encrypted settings archive','','file',['required'=>'required','accept'=>'.cysettings']);partial('factor_proof',['factorRequired'=>$factorRequired]);button('Verify and import for review','secondary full','upload'); ?></form></section></div>
<section class="panel"><div class="section-heading"><h2><?= t('Saved snapshots') ?></h2><span class="pill"><?= t('Secrets encrypted') ?></span></div><div class="vault-list"><?php foreach($a->configuration->listing($uid) as $snapshot): ?><article><div class="row between wrap"><div><strong><?= e($snapshot['label']) ?></strong><p class="hint">#<?= (int)$snapshot['id'] ?> / <?= dt((int)$snapshot['created_at'],'Y.m.d H:i') ?></p></div><a class="btn secondary small" href="<?= e(au('configuration',['preview'=>$snapshot['id']])) ?>"><?= t('Preview differences') ?><?= icon('arrow') ?></a></div><details><summary><?= t('Export encrypted archive') ?></summary><?= form_start('admin_snapshot_export','','',false).hidden('id',$snapshot['id']) ?><?php partial('factor_proof',['factorRequired'=>$factorRequired]);button('Verify and export','secondary small','download'); ?></form></details></article><?php endforeach ?></div></section>
